window.TEXTOS_SEED["numeros"][30] = [
{s:"Os votos"},
{v:1,t:"Moisés disse aos filhos de Israel tudo o que o Senhor lhe ordenara."},
{v:2,t:"Moisés falou aos chefes das tribos dos filhos de Israel, dizendo: Isto é o que o Senhor ordenou:"},
{v:3,t:"Quando um homem fizer voto ao Senhor, ou se obrigar com juramento, não quebrará a sua palavra: fará conforme tudo o que saiu da sua boca.",n:"É a este princípio que o Sermão da Montanha responde, não para o abrandar, mas para o levar além: não jureis de modo algum, e seja o vosso falar sim, sim; não, não."},
{s:"O voto da mulher"},
{v:4,t:"Quando uma mulher, na sua juventude, ainda em casa de seu pai, fizer voto ao Senhor ou se obrigar,"},
{v:5,t:"e seu pai souber do voto e da obrigação com que se ligou, e se calar, valerão todos os seus votos e todas as obrigações com que se ligou."},
{v:6,t:"Mas, se seu pai, no dia em que souber, a contradisser, não valerão os seus votos nem as obrigações com que se ligou; e o Senhor a perdoará, porque seu pai a contradisse."},
{v:7,t:"Se for casada e tiver sobre si votos, ou palavra saída dos seus lábios com que se obrigou,",np:1},
{v:8,t:"e seu marido souber e se calar no dia em que souber, valerão os seus votos e as obrigações com que se ligou."},
{v:9,t:"Mas, se no dia em que souber ele a contradisser, anulará o voto que ela tinha sobre si e a palavra irrefletida com que se obrigou; e o Senhor a perdoará."},
{v:10,t:"O voto da viúva e da repudiada, tudo aquilo com que se obrigaram, valerá sobre elas.",n:"A viúva e a repudiada respondem por si, sem que ninguém possa anular-lhes a palavra: a restrição dos outros casos supõe a dependência da casa, e cessa com ela."},
{v:11,t:"Se ela fez voto em casa do marido, ou se obrigou com juramento,",np:1},
{v:12,t:"e o marido soube e se calou, sem a contradizer, valerão todos os seus votos e todas as obrigações com que se ligou."},
{v:13,t:"Mas, se o marido os anulou no dia em que os soube, não valerá nada do que saiu dos seus lábios, quanto aos votos e às obrigações; o marido os anulou, e o Senhor a perdoará."},
{v:14,t:"Todo voto e todo juramento que a obrigue a afligir-se, o marido pode confirmá-lo ou anulá-lo."},
{v:15,t:"Se o marido se calar de um dia para outro, confirma todos os votos e todas as obrigações que ela tem sobre si: confirma-os por se ter calado no dia em que os soube."},
{v:16,t:"Se os anular depois de os ter sabido, levará ele a iniquidade dela.",n:"Quem anula fora do prazo carrega ele mesmo a falta: o direito de impedir tem hora certa, e passada ela a responsabilidade muda de lado."},
{v:17,t:"Estas são as leis que o Senhor ordenou a Moisés, entre o marido e a mulher, entre o pai e a filha, que na sua juventude está ainda em casa de seu pai."}
];

window.TEXTOS_SEED["numeros"][31] = [
{s:"A guerra contra Madiã"},
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Vinga os filhos de Israel dos madianitas, e depois serás reunido ao teu povo.",n:"O capítulo é dos mais duros da Escritura, e a tradição nunca o leu como norma de guerra, mas como relato de um episódio determinado, ligado à sedução de Fogor. A Igreja lê a Lei antiga à luz do mandamento novo, que manda amar os inimigos."},
{v:3,t:"Moisés falou ao povo, dizendo: Armai alguns homens para a guerra, que vão contra Madiã e executem a vingança do Senhor sobre Madiã."},
{v:4,t:"Enviareis à guerra mil homens de cada tribo de Israel."},
{v:5,t:"Deram-se, dos milhares de Israel, mil por tribo: doze mil homens armados para a guerra."},
{v:6,t:"Moisés os enviou, mil por tribo, com Fineias, filho do sacerdote Eleazar, que levava os utensílios sagrados e as trombetas do alarme."},
{v:7,t:"Pelejaram contra Madiã, como o Senhor ordenara a Moisés, e mataram todos os varões."},
{v:8,t:"Entre os mortos estavam os reis de Madiã: Evi, Recem, Sur, Hur e Rebe, cinco reis de Madiã; também mataram à espada Balaão, filho de Beor.",n:"Balaão, que abençoara Israel por quatro vezes, morre entre os inimigos: o versículo 16 dirá que foi dele o conselho que levou o povo a Fogor."},
{v:9,t:"Os filhos de Israel levaram cativas as mulheres de Madiã e os seus pequeninos, e tomaram todo o seu gado, todos os seus rebanhos e todos os seus bens;"},
{v:10,t:"puseram fogo a todas as suas cidades, às suas aldeias e a todos os seus acampamentos."},
{v:11,t:"Tomaram todo o despojo e tudo o que tinham tomado, homens e animais,"},
{v:12,t:"e levaram os cativos, o que tinham tomado e o despojo a Moisés, ao sacerdote Eleazar e à assembleia dos filhos de Israel, ao arraial, nas planícies de Moab, junto ao Jordão, defronte de Jericó."},
{s:"A ira de Moisés"},
{v:13,t:"Moisés, o sacerdote Eleazar e todos os príncipes da assembleia saíram ao seu encontro fora do arraial."},
{v:14,t:"Moisés irou-se contra os chefes do exército, os chefes de mil e os chefes de cem que voltavam da guerra,"},
{v:15,t:"e disse a eles: Por que deixastes com vida todas as mulheres?"},
{v:16,t:"Foram elas que, por conselho de Balaão, levaram os filhos de Israel à infidelidade contra o Senhor, no caso de Fogor, e por isso houve praga na assembleia do Senhor."},
{v:17,t:"Matai, pois, todo varão entre os pequeninos e matai toda mulher que conheceu varão;"},
{v:18,t:"mas deixai com vida, para vós, todas as meninas que não conheceram varão."},
{s:"A purificação"},
{v:19,t:"Ficai sete dias fora do arraial; todo o que matou alguém e todo o que tocou um morto há de purificar-se ao terceiro e ao sétimo dia, vós e os vossos cativos.",n:"Mesmo a guerra tida por justa deixa impuro quem a fez: o vencedor não entra no arraial sem passar pelo rito da novilha vermelha, do capítulo 19."},
{v:20,t:"Purificareis também toda veste, todo objeto de pele, toda obra de pelo de cabra e todo utensílio de madeira."},
{v:21,t:"O sacerdote Eleazar disse aos homens do exército que tinham ido à guerra: Este é o preceito da lei que o Senhor ordenou a Moisés:"},
{v:22,t:"o ouro, a prata, o bronze, o ferro, o estanho e o chumbo,"},
{v:23,t:"tudo o que pode passar pelo fogo, haveis de passá-lo pelo fogo, e ficará puro; mas há de purificar-se também com a água de purificação. Tudo o que não pode passar pelo fogo, haveis de passá-lo pela água."},
{v:24,t:"Lavareis as vossas vestes ao sétimo dia, e ficareis puros; depois entrareis no arraial."},
{s:"A repartição do despojo"},
{v:25,t:"O Senhor falou a Moisés, dizendo:"},
{v:26,t:"Faze a conta do que foi tomado, dos homens e dos animais, tu, o sacerdote Eleazar e os chefes das casas paternas da assembleia;"},
{v:27,t:"e reparte o despojo em duas partes: entre os que pelejaram e saíram à guerra e toda a assembleia.",n:"Metade para os doze mil que combateram e metade para todo o povo, que ficou: quem não foi à peleja não fica sem parte, e quem foi não leva tudo."},
{v:28,t:"Separarás para o Senhor, dos homens de guerra que saíram à peleja, uma parte em quinhentas: das pessoas, dos bois, dos jumentos e das ovelhas."},
{v:29,t:"Da sua metade o tomarás e o darás ao sacerdote Eleazar, como oferta do Senhor."},
{v:30,t:"Da metade dos filhos de Israel tomarás uma parte em cinquenta: das pessoas, dos bois, dos jumentos, das ovelhas e de todos os animais; e as darás aos levitas, que guardam o que toca ao tabernáculo do Senhor."},
{v:31,t:"Moisés e o sacerdote Eleazar fizeram como o Senhor ordenara a Moisés.",np:1},
{v:32,t:"O despojo, o resto do que o exército tomara, foi de seiscentas e setenta e cinco mil ovelhas,"},
{v:33,t:"setenta e dois mil bois,"},
{v:34,t:"sessenta e um mil jumentos,"},
{v:35,t:"e trinta e duas mil pessoas, mulheres que não tinham conhecido varão."},
{v:36,t:"A metade que coube aos que saíram à guerra foi de trezentas e trinta e sete mil e quinhentas ovelhas,",np:1},
{v:37,t:"das quais se separaram para o Senhor seiscentas e setenta e cinco;"},
{v:38,t:"trinta e seis mil bois, dos quais se separaram para o Senhor setenta e dois;"},
{v:39,t:"trinta mil e quinhentos jumentos, dos quais se separaram para o Senhor sessenta e um;"},
{v:40,t:"e dezesseis mil pessoas, das quais se separaram para o Senhor trinta e duas."},
{v:41,t:"Moisés deu ao sacerdote Eleazar a parte separada como oferta do Senhor, conforme o Senhor lhe ordenara."},
{v:42,t:"Da metade que coube aos filhos de Israel, que Moisés separara da dos homens que pelejaram —",np:1},
{v:43,t:"essa metade da assembleia foi de trezentas e trinta e sete mil e quinhentas ovelhas,"},
{v:44,t:"trinta e seis mil bois,"},
{v:45,t:"trinta mil e quinhentos jumentos"},
{v:46,t:"e dezesseis mil pessoas."},
{v:47,t:"Da metade dos filhos de Israel Moisés tomou uma parte em cinquenta, das pessoas e dos animais, e as deu aos levitas, que guardavam o que tocava ao tabernáculo do Senhor, como o Senhor lhe ordenara."},
{s:"A oferta dos chefes"},
{v:48,t:"Os chefes do exército, os chefes de mil e os chefes de cem, aproximaram-se de Moisés"},
{v:49,t:"e disseram a ele: Os teus servos fizeram a conta dos homens de guerra que estavam sob a nossa mão, e não falta nenhum de nós."},
{v:50,t:"Por isso trazemos como oferta ao Senhor o que cada um achou de objetos de ouro: braceletes, pulseiras, anéis, brincos e colares, para fazer expiação pelas nossas almas diante do Senhor."},
{v:51,t:"Moisés e o sacerdote Eleazar receberam deles o ouro, todo lavrado em objetos."},
{v:52,t:"Todo o ouro da oferta que apresentaram ao Senhor, da parte dos chefes de mil e dos chefes de cem, foi de dezesseis mil setecentos e cinquenta siclos."},
{v:53,t:"Os homens do exército tomaram cada um o seu despojo."},
{v:54,t:"Moisés e o sacerdote Eleazar receberam o ouro dos chefes de mil e de cem e o levaram à tenda do encontro, como memorial dos filhos de Israel diante do Senhor."}
];

window.TEXTOS_SEED["numeros"][32] = [
{s:"O pedido de Rúben e Gad"},
{v:1,t:"Os filhos de Rúben e os filhos de Gad tinham muitíssimo gado; viram que a terra de Jazer e a terra de Galaad eram lugar próprio para o gado."},
{v:2,t:"Vieram os filhos de Gad e os filhos de Rúben e disseram a Moisés, ao sacerdote Eleazar e aos príncipes da assembleia:"},
{v:3,t:"Atarot, Dibon, Jazer, Nemra, Hesbon, Eleale, Sabam, Nebo e Beon,"},
{v:4,t:"a terra que o Senhor feriu diante da assembleia de Israel, é terra própria para o gado, e os teus servos têm gado."},
{v:5,t:"E disseram: Se achamos graça aos teus olhos, dê-se esta terra aos teus servos em propriedade; não nos faças passar o Jordão."},
{s:"A repreensão de Moisés"},
{v:6,t:"Moisés respondeu aos filhos de Gad e aos filhos de Rúben: Acaso os vossos irmãos irão à guerra, e vós ficareis aqui sentados?"},
{v:7,t:"Por que desanimais o coração dos filhos de Israel, para que não passem à terra que o Senhor lhes deu?"},
{v:8,t:"Assim fizeram vossos pais, quando os enviei de Cades-Barne a explorar a terra."},
{v:9,t:"Subiram até ao vale de Escol, viram a terra e desanimaram o coração dos filhos de Israel, para que não entrassem na terra que o Senhor lhes deu."},
{v:10,t:"A ira do Senhor acendeu-se naquele dia, e ele jurou, dizendo:"},
{v:11,t:"Os homens que subiram do Egito, dos vinte anos para cima, não verão a terra que jurei a Abraão, a Isaac e a Jacó, porque não me seguiram inteiramente,"},
{v:12,t:"exceto Caleb, filho de Jefoné, o quenezeu, e Josué, filho de Nun, porque seguiram o Senhor inteiramente."},
{v:13,t:"A ira do Senhor acendeu-se contra Israel, e ele os fez andar errantes pelo deserto quarenta anos, até acabar toda a geração que fizera o mal aos olhos do Senhor."},
{v:14,t:"E eis que vós vos levantastes em lugar de vossos pais, ninhada de homens pecadores, para aumentar ainda o furor da ira do Senhor contra Israel."},
{v:15,t:"Se vos desviardes de segui-lo, ele tornará a deixar o povo no deserto, e sereis vós a causa da perdição de todo este povo."},
{s:"O acordo"},
{v:16,t:"Aproximaram-se dele e disseram: Edificaremos aqui currais para o nosso gado e cidades para os nossos pequeninos;"},
{v:17,t:"mas nós iremos armados e prontos diante dos filhos de Israel, até os levarmos ao seu lugar. Os nossos pequeninos ficarão nas cidades fortificadas, por causa dos habitantes da terra."},
{v:18,t:"Não voltaremos às nossas casas até que os filhos de Israel possuam cada um a sua herança;"},
{v:19,t:"e não receberemos herança com eles além do Jordão, porque a nossa herança nos coube deste lado do Jordão, ao oriente."},
{v:20,t:"Moisés disse a eles: Se fizerdes o que dissestes, se fordes armados à guerra diante do Senhor,",np:1},
{v:21,t:"e todos os vossos homens armados passarem o Jordão diante do Senhor, até que ele expulse os seus inimigos de diante de si,"},
{v:22,t:"e a terra seja submetida diante do Senhor, então voltareis e ficareis sem culpa diante do Senhor e diante de Israel, e esta terra será vossa propriedade diante do Senhor."},
{v:23,t:"Mas, se não fizerdes assim, eis que pecareis contra o Senhor; e sabei que o vosso pecado vos há de alcançar."},
{v:24,t:"Edificai, pois, cidades para os vossos pequeninos e currais para os vossos rebanhos; e cumpri o que prometestes."},
{v:25,t:"Os filhos de Gad e os filhos de Rúben disseram a Moisés: Os teus servos farão como o meu senhor ordena.",np:1},
{v:26,t:"Os nossos pequeninos, as nossas mulheres, os nossos rebanhos e todo o nosso gado ficarão nas cidades de Galaad;"},
{v:27,t:"e os teus servos, todos armados para a guerra, passarão diante do Senhor à peleja, como o meu senhor diz."},
{v:28,t:"Moisés deu ordem a respeito deles ao sacerdote Eleazar, a Josué, filho de Nun, e aos chefes das casas paternas das tribos dos filhos de Israel;"},
{v:29,t:"e disse a eles: Se os filhos de Gad e os filhos de Rúben passarem convosco o Jordão, todos armados à guerra diante do Senhor, e a terra vos for submetida, haveis de dar-lhes a terra de Galaad em propriedade."},
{v:30,t:"Mas, se não passarem armados convosco, receberão propriedade entre vós na terra de Canaã."},
{v:31,t:"Os filhos de Gad e os filhos de Rúben responderam: Faremos o que o Senhor disse aos teus servos."},
{v:32,t:"Passaremos armados diante do Senhor à terra de Canaã, e conosco ficará a propriedade da nossa herança deste lado do Jordão."},
{s:"A repartição da Transjordânia"},
{v:33,t:"Moisés deu aos filhos de Gad, aos filhos de Rúben e à meia tribo de Manassés, filho de José, o reino de Seon, rei dos amorreus, e o reino de Og, rei de Basã: a terra com as suas cidades e os territórios ao redor."},
{v:34,t:"Os filhos de Gad edificaram Dibon, Atarot, Aroer,"},
{v:35,t:"Atarot-Sofan, Jazer, Jegbaa,"},
{v:36,t:"Bet-Nemra e Bet-Haran, cidades fortificadas, e currais para os rebanhos."},
{v:37,t:"Os filhos de Rúben edificaram Hesbon, Eleale, Cariataim,",np:1},
{v:38,t:"Nebo e Baal-Meon, mudados os nomes, e Sabama; e deram nomes às cidades que edificaram.",n:"Mudados os nomes: Nebo e Baal-Meon traziam nomes de deuses, e por isso se trocaram. O escrúpulo é o mesmo do Êxodo, que manda não repetir o nome de outros deuses."},
{v:39,t:"Os filhos de Maquir, filho de Manassés, foram a Galaad, tomaram-na e expulsaram o amorreu que nela estava.",np:1},
{v:40,t:"Moisés deu Galaad a Maquir, filho de Manassés, e ele habitou nela."},
{v:41,t:"Jair, filho de Manassés, foi e tomou as suas aldeias, e chamou-as Havot-Jair."},
{v:42,t:"Nobe foi e tomou Canat com as suas aldeias, e chamou-lhe Nobe, do seu próprio nome."}
];

window.TEXTOS_SEED["numeros"][33] = [
{s:"As etapas desde o Egito"},
{v:1,t:"Estas são as etapas dos filhos de Israel, que saíram da terra do Egito segundo os seus grupos, por meio de Moisés e Aarão."},
{v:2,t:"Moisés escreveu as suas partidas, segundo as etapas, por ordem do Senhor; estas são as suas etapas segundo as suas partidas.",n:"Raro aviso de que Moisés escreve por ordem expressa. A lista tem quarenta e duas etapas, e vários dos nomes não voltam a aparecer em parte alguma da Escritura."},
{v:3,t:"Partiram de Ramessés no primeiro mês, no dia quinze do primeiro mês; no dia seguinte à Páscoa, os filhos de Israel saíram de mão levantada, à vista de todos os egípcios,"},
{v:4,t:"enquanto estes sepultavam os primogênitos que o Senhor ferira; também sobre os seus deuses o Senhor executara juízos."},
{v:5,t:"Os filhos de Israel partiram de Ramessés e acamparam em Sucot.",np:1},
{v:6,t:"Partiram de Sucot e acamparam em Etam, que está nos confins do deserto."},
{v:7,t:"Partiram de Etam, voltaram para Fiairot, que está defronte de Baal-Sefon, e acamparam diante de Magdol."},
{v:8,t:"Partiram de Fiairot, passaram pelo meio do mar para o deserto, andaram três dias pelo deserto de Etam e acamparam em Mara."},
{v:9,t:"Partiram de Mara e chegaram a Elim, onde havia doze fontes de água e setenta palmeiras; e ali acamparam."},
{v:10,t:"Partiram de Elim e acamparam junto ao mar Vermelho."},
{v:11,t:"Partiram do mar Vermelho e acamparam no deserto de Sin."},
{v:12,t:"Partiram do deserto de Sin e acamparam em Dafca."},
{v:13,t:"Partiram de Dafca e acamparam em Alus."},
{v:14,t:"Partiram de Alus e acamparam em Rafidim, onde não havia água para o povo beber."},
{v:15,t:"Partiram de Rafidim e acamparam no deserto do Sinai."},
{v:16,t:"Partiram do deserto do Sinai e acamparam em Quibrot-Hataavá.",np:1},
{v:17,t:"Partiram de Quibrot-Hataavá e acamparam em Haserot."},
{v:18,t:"Partiram de Haserot e acamparam em Retma."},
{v:19,t:"Partiram de Retma e acamparam em Remon-Farés."},
{v:20,t:"Partiram de Remon-Farés e acamparam em Lebna."},
{v:21,t:"Partiram de Lebna e acamparam em Ressa."},
{v:22,t:"Partiram de Ressa e acamparam em Ceelata."},
{v:23,t:"Partiram de Ceelata e acamparam no monte Séfer."},
{v:24,t:"Partiram do monte Séfer e acamparam em Arada."},
{v:25,t:"Partiram de Arada e acamparam em Maceló."},
{v:26,t:"Partiram de Maceló e acamparam em Taat."},
{v:27,t:"Partiram de Taat e acamparam em Taré."},
{v:28,t:"Partiram de Taré e acamparam em Metca."},
{v:29,t:"Partiram de Metca e acamparam em Hesmona."},
{v:30,t:"Partiram de Hesmona e acamparam em Moserot."},
{v:31,t:"Partiram de Moserot e acamparam em Benê-Jaacan."},
{v:32,t:"Partiram de Benê-Jaacan e acamparam em Hor-Gidgad."},
{v:33,t:"Partiram de Hor-Gidgad e acamparam em Jetebata."},
{v:34,t:"Partiram de Jetebata e acamparam em Hebrona."},
{v:35,t:"Partiram de Hebrona e acamparam em Asion-Gaber."},
{v:36,t:"Partiram de Asion-Gaber e acamparam no deserto de Sin, que é Cades."},
{v:37,t:"Partiram de Cades e acamparam no monte Hor, na fronteira da terra de Edom.",np:1},
{v:38,t:"O sacerdote Aarão subiu ao monte Hor por ordem do Senhor e ali morreu, no quadragésimo ano da saída dos filhos de Israel da terra do Egito, no quinto mês, no primeiro dia do mês.",n:"É a única data exata em toda a lista: o itinerário para na morte do sacerdote, como quem marca o fim de uma geração."},
{v:39,t:"Aarão tinha cento e vinte e três anos quando morreu no monte Hor."},
{v:40,t:"O cananeu, rei de Arad, que habitava no Negueb, na terra de Canaã, ouviu que vinham os filhos de Israel."},
{v:41,t:"Partiram do monte Hor e acamparam em Salmona.",np:1},
{v:42,t:"Partiram de Salmona e acamparam em Funon."},
{v:43,t:"Partiram de Funon e acamparam em Obot."},
{v:44,t:"Partiram de Obot e acamparam em Ijé-Abarim, na fronteira de Moab."},
{v:45,t:"Partiram de Ijé-Abarim e acamparam em Dibon-Gad."},
{v:46,t:"Partiram de Dibon-Gad e acamparam em Helmon-Deblataim."},
{v:47,t:"Partiram de Helmon-Deblataim e acamparam nos montes Abarim, defronte de Nebo."},
{v:48,t:"Partiram dos montes Abarim e acamparam nas planícies de Moab, junto ao Jordão, defronte de Jericó."},
{v:49,t:"Acamparam junto ao Jordão, desde Bet-Jesimot até Abel-Sitim, nas planícies de Moab."},
{s:"A ordem de expulsar os cananeus"},
{v:50,t:"O Senhor falou a Moisés nas planícies de Moab, junto ao Jordão, defronte de Jericó, dizendo:"},
{v:51,t:"Fala aos filhos de Israel e dize a eles: Quando passardes o Jordão para a terra de Canaã,"},
{v:52,t:"expulsareis de diante de vós todos os habitantes da terra, destruireis todas as suas imagens, todas as suas estátuas fundidas e devastareis todos os seus altos."},
{v:53,t:"Tomareis posse da terra e nela habitareis, porque eu vos dei essa terra em propriedade."},
{v:54,t:"Repartireis a terra por sorte, segundo as vossas famílias: aos mais numerosos dareis herança maior, e aos menos numerosos, herança menor; onde a sorte cair a cada um, ali será a sua parte; segundo as tribos de vossos pais recebereis a herança."},
{v:55,t:"Mas, se não expulsardes de diante de vós os habitantes da terra, os que deixardes ficar serão como espinhos nos vossos olhos e aguilhões nos vossos lados, e vos hostilizarão na terra em que habitardes;",n:"O livro dos Juízes abrirá contando que foi isso mesmo o que sucedeu; a advertência lê-se ali como profecia cumprida."},
{v:56,t:"e farei convosco o que pensara fazer com eles."}
];

window.TEXTOS_SEED["numeros"][34] = [
{s:"Os limites da terra"},
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Ordena aos filhos de Israel e dize a eles: Quando entrardes na terra de Canaã, esta é a terra que vos cairá em herança, a terra de Canaã, segundo os seus limites."},
{v:3,t:"O lado meridional começará no deserto de Sin, junto a Edom; o limite do sul será desde a extremidade do mar Salgado, ao oriente;"},
{v:4,t:"virará ao sul pela subida de Acrabim, passará a Sin e chegará ao sul de Cades-Barne; seguirá a Hasar-Adar e passará a Asmon;"},
{v:5,t:"de Asmon virará para a torrente do Egito e terminará no mar."},
{v:6,t:"O limite ocidental será o mar Grande: esse será o vosso limite ao ocidente.",np:1,n:"O mar Grande é o Mediterrâneo. Os limites aqui traçados são mais largos do que Israel jamais ocupou de facto."},
{v:7,t:"Este será o vosso limite ao norte: do mar Grande traçareis a linha até ao monte Hor;",np:1},
{v:8,t:"do monte Hor até à entrada de Emat; o limite chegará a Sedada;"},
{v:9,t:"seguirá a Zefrona e terminará em Hasar-Enan: esse será o vosso limite ao norte."},
{v:10,t:"Traçareis o vosso limite oriental desde Hasar-Enan até Sefama;",np:1},
{v:11,t:"de Sefama descerá a Rebla, ao oriente de Ain; descerá e chegará à encosta do mar de Ceneret, ao oriente;"},
{v:12,t:"descerá ao Jordão e terminará no mar Salgado. Esta será a vossa terra, segundo os seus limites ao redor."},
{v:13,t:"Moisés ordenou aos filhos de Israel: Esta é a terra que recebereis por sorte, e que o Senhor ordenou dar às nove tribos e à meia tribo.",np:1},
{v:14,t:"Porque a tribo dos filhos de Rúben, segundo as suas casas paternas, a tribo dos filhos de Gad, segundo as suas casas paternas, e a meia tribo de Manassés já receberam a sua herança;"},
{v:15,t:"duas tribos e meia receberam a sua herança além do Jordão, defronte de Jericó, ao oriente."},
{s:"Os que hão de repartir a terra"},
{v:16,t:"O Senhor falou a Moisés, dizendo:"},
{v:17,t:"Estes são os nomes dos homens que vos repartirão a terra: o sacerdote Eleazar e Josué, filho de Nun;"},
{v:18,t:"e tomareis um príncipe de cada tribo, para repartir a terra."},
{v:19,t:"Estes são os nomes dos homens: da tribo de Judá, Caleb, filho de Jefoné;",np:1},
{v:20,t:"da tribo dos filhos de Simeão, Samuel, filho de Amiud;"},
{v:21,t:"da tribo de Benjamim, Elidad, filho de Caselon;"},
{v:22,t:"da tribo dos filhos de Dã, o príncipe Boci, filho de Jogli;"},
{v:23,t:"dos filhos de José, da tribo dos filhos de Manassés, o príncipe Haniel, filho de Efod;"},
{v:24,t:"da tribo dos filhos de Efraim, o príncipe Camuel, filho de Seftan;"},
{v:25,t:"da tribo dos filhos de Zabulon, o príncipe Elisafan, filho de Farnac;"},
{v:26,t:"da tribo dos filhos de Issacar, o príncipe Faltiel, filho de Ozan;"},
{v:27,t:"da tribo dos filhos de Aser, o príncipe Aiud, filho de Salomi;"},
{v:28,t:"da tribo dos filhos de Neftali, o príncipe Fedael, filho de Amiud."},
{v:29,t:"Estes são aqueles a quem o Senhor ordenou que repartissem aos filhos de Israel a terra de Canaã."}
];

window.TEXTOS_SEED["numeros"][35] = [
{s:"As cidades dos levitas"},
{v:1,t:"O Senhor falou a Moisés nas planícies de Moab, junto ao Jordão, defronte de Jericó, dizendo:"},
{v:2,t:"Ordena aos filhos de Israel que deem aos levitas, da herança que possuírem, cidades para habitar, e também os arredores das cidades.",n:"Levi não tem território, mas há de morar em alguma parte: as quarenta e oito cidades espalham-se por todas as tribos, e assim a tribo sem terra fica presente em toda a terra."},
{v:3,t:"As cidades serão para eles habitarem, e os arredores serão para os seus animais, os seus bens e todos os seus rebanhos."},
{v:4,t:"Os arredores das cidades que dareis aos levitas se estenderão, do muro da cidade para fora, mil côvados ao redor."},
{v:5,t:"Medireis fora da cidade dois mil côvados ao oriente, dois mil ao sul, dois mil ao ocidente e dois mil ao norte, ficando a cidade no meio: estes serão os arredores das cidades."},
{v:6,t:"Das cidades que dareis aos levitas, seis serão de refúgio, que destinareis para que se refugie o homicida; além destas dareis outras quarenta e duas."},
{v:7,t:"Todas as cidades que dareis aos levitas serão quarenta e oito, com os seus arredores."},
{v:8,t:"As cidades que derdes da propriedade dos filhos de Israel: dos que têm mais, dareis mais; dos que têm menos, menos; cada um dará das suas cidades aos levitas, segundo a herança que receber."},
{s:"As cidades de refúgio"},
{v:9,t:"O Senhor falou a Moisés, dizendo:"},
{v:10,t:"Fala aos filhos de Israel e dize a eles: Quando passardes o Jordão para a terra de Canaã,"},
{v:11,t:"escolhereis cidades que vos sirvam de refúgio, para que nelas se refugie o homicida que matar alguém por engano.",n:"A instituição corta o ciclo da vingança de sangue: entre o parente do morto e o que matou sem querer interpõe-se um lugar e um juízo."},
{v:12,t:"Servirão de refúgio contra o vingador do sangue, para que o homicida não morra antes de comparecer em juízo diante da assembleia."},
{v:13,t:"Das cidades que derdes, seis serão de refúgio."},
{v:14,t:"Dareis três além do Jordão e três na terra de Canaã: serão cidades de refúgio."},
{v:15,t:"Para os filhos de Israel, para o estrangeiro e para o que peregrina entre vós, essas seis cidades serão de refúgio, para que se refugie ali todo o que matar alguém por engano."},
{s:"O homicida e o vingador do sangue"},
{v:16,t:"Se alguém ferir outro com instrumento de ferro, e este morrer, é homicida: o homicida morrerá."},
{v:17,t:"Se ferir com uma pedra na mão, com a qual se pode matar, e o outro morrer, é homicida: o homicida morrerá."},
{v:18,t:"Se ferir com um instrumento de madeira na mão, com o qual se pode matar, e o outro morrer, é homicida: o homicida morrerá."},
{v:19,t:"O vingador do sangue matará o homicida; quando o encontrar, ele o matará."},
{v:20,t:"Se alguém empurrar outro por ódio, ou lançar sobre ele alguma coisa de emboscada, e ele morrer,",np:1},
{v:21,t:"ou, por inimizade, o ferir com a mão, e ele morrer, o que feriu morrerá: é homicida; o vingador do sangue o matará quando o encontrar."},
{v:22,t:"Mas, se por acaso, sem inimizade, o empurrar, ou lançar sobre ele qualquer coisa sem emboscada,",np:1,n:"A distinção entre o que matou de propósito e o que matou por acaso é aqui posta com um cuidado sem paralelo no direito antigo do Oriente, e pesa a intenção antes do resultado."},
{v:23,t:"ou deixar cair sobre ele uma pedra com que se pode matar, sem o ver, e ele morrer, não sendo seu inimigo nem procurando o seu mal,"},
{v:24,t:"a assembleia julgará entre o que feriu e o vingador do sangue, segundo estas normas."},
{v:25,t:"A assembleia livrará o homicida da mão do vingador do sangue e o fará voltar à cidade de refúgio para onde tinha fugido; ali ficará até à morte do sumo sacerdote que foi ungido com o óleo santo."},
{v:26,t:"Se o homicida sair dos limites da cidade de refúgio para onde fugiu,",np:1},
{v:27,t:"e o vingador do sangue o encontrar fora dos limites da cidade de refúgio e o matar, não será culpado de sangue,"},
{v:28,t:"porque o homicida devia ficar na cidade de refúgio até à morte do sumo sacerdote; depois da morte do sumo sacerdote poderá voltar à terra da sua propriedade.",n:"A morte do sumo sacerdote abre as portas do refúgio: uma morte põe fim ao exílio de todos os que ali estavam, e os padres da Igreja liam nisso uma figura."},
{v:29,t:"Isto será para vós norma de direito, por vossas gerações, em todas as vossas habitações."},
{s:"As testemunhas e o resgate"},
{v:30,t:"Todo o que matar alguém será morto mediante testemunhas; mas uma só testemunha não bastará para condenar alguém à morte."},
{v:31,t:"Não aceitareis resgate pela vida do homicida, que é réu de morte: ele morrerá.",n:"Quase tudo se podia resgatar com dinheiro; a vida humana, não. A proibição impede que o rico compre a impunidade."},
{v:32,t:"Nem aceitareis resgate do que fugiu para a cidade de refúgio, para que volte a habitar na terra antes da morte do sumo sacerdote."},
{v:33,t:"Não profanareis a terra em que estais, porque o sangue profana a terra, e a terra não pode ser expiada do sangue nela derramado senão pelo sangue daquele que o derramou."},
{v:34,t:"Não contamineis a terra em que habitais, no meio da qual eu habito, porque eu, o Senhor, habito no meio dos filhos de Israel."}
];

window.TEXTOS_SEED["numeros"][36] = [
{s:"A herança das filhas de Salfaad"},
{v:1,t:"Aproximaram-se os chefes das casas paternas da família dos filhos de Galaad, filho de Maquir, filho de Manassés, das famílias dos filhos de José, e falaram diante de Moisés e dos príncipes, chefes das casas paternas dos filhos de Israel,"},
{v:2,t:"e disseram: O Senhor ordenou ao meu senhor que repartisse por sorte a terra aos filhos de Israel, e o meu senhor recebeu do Senhor a ordem de dar a herança de Salfaad, nosso irmão, às suas filhas."},
{v:3,t:"Se elas se casarem com filhos de outra tribo dos filhos de Israel, a sua herança será tirada da herança de nossos pais e acrescentada à herança da tribo a que passarem; assim será tirada da sorte da nossa herança."},
{v:4,t:"Quando chegar o jubileu dos filhos de Israel, a herança delas será acrescentada à herança da tribo a que passarem; e a sua herança será tirada da herança da tribo de nossos pais."},
{v:5,t:"Moisés ordenou aos filhos de Israel, por ordem do Senhor: A tribo dos filhos de José fala com razão.",n:"A mesma fórmula com que o Senhor acolhera o pedido das filhas, no capítulo 27. As duas partes têm razão, e a solução guarda o direito delas sem desfazer o das tribos."},
{v:6,t:"Isto é o que o Senhor ordenou a respeito das filhas de Salfaad: casem-se com quem lhes agradar, contanto que se casem dentro da família da tribo de seu pai,"},
{v:7,t:"para que a herança dos filhos de Israel não passe de tribo em tribo, mas cada um dos filhos de Israel se mantenha na herança da tribo de seus pais."},
{v:8,t:"Toda filha que receber herança nas tribos dos filhos de Israel há de casar-se com alguém da família da tribo de seu pai, para que os filhos de Israel possuam cada um a herança de seus pais,"},
{v:9,t:"e a herança não passe de uma tribo a outra, mas cada uma das tribos dos filhos de Israel se mantenha na sua herança."},
{v:10,t:"As filhas de Salfaad fizeram como o Senhor ordenara a Moisés:",np:1},
{v:11,t:"Maala, Tersa, Hegla, Melca e Noa casaram-se com os filhos de seus tios."},
{v:12,t:"Casaram-se dentro das famílias dos filhos de Manassés, filho de José, e a sua herança ficou na tribo da família de seu pai."},
{v:13,t:"Estes são os mandamentos e as normas de direito que o Senhor ordenou aos filhos de Israel, por meio de Moisés, nas planícies de Moab, junto ao Jordão, defronte de Jericó.",n:"O livro fecha onde parou a marcha, às portas da terra e sem entrar nela: o Pentateuco inteiro termina assim, do lado de fora."}
];
